/**
 * 模拟 IC 检测手布（2 层）：
 * 上：UA741→TL082→LM358 信号链；右上 LM555；下：三路线性稳压 + LM2596 Buck。
 * VCC 顶 F 总线 + 底 B 廊；信号本地短连；排针扇出长跑走 B。
 */
function handLayoutLabAnalogIc(doc) {
  doc.tracks = [];
  doc.vias = [];
  doc.zones = [];
  doc.footprints = doc.footprints.filter(f => !!f.schematicCompId);

  {
    const fp = doc.footprints.find(f => f.refDes === 'U4');
    if (fp && fp.defId !== 'FP_SIP5') {
      const neu = instantiate('FP_SIP5', 'U4', fp.value || 'LM2596', fp.position, 0, fp.schematicCompId);
      fp.defId = neu.defId;
      fp.pads = neu.pads;
      for (const pad of fp.pads) { pad.netId = undefined; pad.netName = undefined; }
    }
  }

  const byRef = new Map(doc.footprints.map(f => [f.refDes, f]));
  const setPos = (ref, x, y, rot = 0) => {
    const fp = byRef.get(ref);
    if (!fp) return;
    fp.position = { x, y };
    fp.rotation = rot;
    fp.mirrored = false;
    fp.layer = 'F.Cu';
  };
  const netByName = (name) => doc.nets.find(n => (n.name || '').toUpperCase() === name);
  const gnd = doc.nets.find(n => isGndNet(n.name));
  const vcc = netByName('VCC');
  const sig = netByName('SIG');
  const bufIn = netByName('BUF_IN');
  const out741 = netByName('OUT741');
  const tlIn = netByName('TL_IN');
  const tlOut = netByName('TL_OUT');
  const u2b = netByName('U2_B_FB');
  const lmIn = netByName('LM_IN');
  const lmFb = netByName('LM_FB');
  const lmOut = netByName('LM_OUT');
  const u3b = netByName('U3_B_FB');
  const vout0 = netByName('VOUT_R0');
  const vout1 = netByName('VOUT_R1');
  const vout2 = netByName('VOUT_R2');
  const buckSw = netByName('BUCK_SW');
  const buckOut = netByName('BUCK_OUT');
  const disch = netByName('DISCH');
  const cap555 = netByName('555_CAP');
  const out555 = netByName('LM555_OUT');
  const led555 = netByName('LED555');
  const ctrl = netByName('CTRL');

  const bindPad = (ref, num, net) => {
    const fp = byRef.get(ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    if (!pad || !net) return;
    pad.netId = net.id;
    pad.netName = net.name;
  };

  bindPad('U1', 2, out741); bindPad('U1', 3, bufIn); bindPad('U1', 4, gnd);
  bindPad('U1', 6, out741); bindPad('U1', 7, vcc);
  bindPad('U2', 1, tlOut); bindPad('U2', 2, tlOut); bindPad('U2', 3, tlIn); bindPad('U2', 4, gnd);
  bindPad('U2', 5, gnd); bindPad('U2', 6, u2b); bindPad('U2', 7, u2b); bindPad('U2', 8, vcc);
  bindPad('U3', 1, lmOut); bindPad('U3', 2, lmFb); bindPad('U3', 3, lmIn); bindPad('U3', 4, gnd);
  bindPad('U3', 5, gnd); bindPad('U3', 6, u3b); bindPad('U3', 7, u3b); bindPad('U3', 8, vcc);
  bindPad('U5', 1, gnd); bindPad('U5', 2, cap555); bindPad('U5', 3, out555);
  bindPad('U5', 4, vcc); bindPad('U5', 5, ctrl); bindPad('U5', 6, cap555);
  bindPad('U5', 7, disch); bindPad('U5', 8, vcc);
  bindPad('U4', 1, vcc); bindPad('U4', 2, buckSw); bindPad('U4', 3, gnd);
  bindPad('U4', 4, buckOut); bindPad('U4', 5, buckOut);
  bindPad('REG1', 1, vcc); bindPad('REG1', 2, gnd); bindPad('REG1', 3, vout0);
  bindPad('REG2', 1, vcc); bindPad('REG2', 2, gnd); bindPad('REG2', 3, vout1);
  bindPad('REG3', 1, vcc); bindPad('REG3', 2, gnd); bindPad('REG3', 3, vout2);

  setPos('R1', 200, 295, 0);
  setPos('U1', 400, 280, 0);
  setPos('R2', 600, 295, 0);
  setPos('U2', 800, 280, 0);
  setPos('R3', 1000, 295, 0);
  setPos('U3', 1200, 280, 0);
  setPos('Rf3', 1340, 235, 0);
  setPos('Rg3', 1040, 400, 0);

  setPos('U5', 1900, 280, 0);
  setPos('RA', 1680, 160, 0);
  setPos('RB', 1680, 295, 0);
  setPos('CT', 1680, 420, 0);
  setPos('CD555', 2120, 160, 0);
  setPos('CC555', 2120, 420, 0);
  setPos('RLED', 2120, 295, 0);
  setPos('D555', 2300, 295, 0);

  for (let i = 0; i < 3; i++) {
    const x = 300 + i * 480;
    setPos(`REG${i + 1}`, x, 800, 0);
    setPos(`CI${i + 1}`, x - 220, 800, 0);
    setPos(`CO${i + 1}`, x + 220, 800, 0);
    setPos(`RL${i + 1}`, x + 220, 940, 0);
  }

  setPos('U4', 1880, 800, 0);
  setPos('CBI', 1520, 800, 0);
  setPos('LB', 2180, 800, 0);
  setPos('CBO', 2380, 800, 0);
  setPos('RFB', 2380, 940, 0);

  const hdr = instantiate('FP_PINHDR_8', 'J1', '1x8', { x: 2720, y: 480 }, 0);
  const hdrNets = [gnd, vcc, sig, lmOut, out555, vout0, buckOut, disch];
  for (let i = 0; i < hdr.pads.length; i++) {
    const n = hdrNets[i];
    if (!n) continue;
    hdr.pads[i].netId = n.id;
    hdr.pads[i].netName = n.name;
  }
  doc.footprints.push(hdr);
  byRef.set('J1', hdr);

  const pw = (ref, num) => {
    const fp = byRef.get(ref) || doc.footprints.find(f => f.refDes === ref);
    const pad = fp?.pads.find(p => p.number === String(num));
    return pad ? padWorld(fp, pad) : null;
  };
  const add = (net, a, b, w = 14, layer = 'F.Cu') => {
    if (!net || !a || !b || dist(a, b) < 0.5) return;
    doc.tracks.push({
      id: uid('trk'), layer,
      start: { x: a.x, y: a.y }, end: { x: b.x, y: b.y },
      width: w, netId: net.id, netName: net.name
    });
  };
  const addVia = (net, p) => {
    if (!net || !p) return;
    for (const v of doc.vias) {
      if (v.netId === net.id && Math.abs(v.position.x - p.x) < 0.5 &&
        Math.abs(v.position.y - p.y) < 0.5) return;
    }
    doc.vias.push({
      id: uid('via'), position: { x: p.x, y: p.y },
      drill: 12, diameter: 24,
      netId: net.id, netName: net.name,
      layers: ['F.Cu', 'B.Cu'], kind: 'through'
    });
  };
  const L = (net, pts, w = 14, layer = 'F.Cu') => {
    for (let i = 0; i < pts.length - 1; i++) add(net, pts[i], pts[i + 1], w, layer);
  };
  const ortho = (net, a, b, w = 12, preferVertFirst = false) => {
    if (!net || !a || !b) return;
    if (Math.abs(a.x - b.x) < 0.5 || Math.abs(a.y - b.y) < 0.5) {
      add(net, a, b, w, 'F.Cu');
      return;
    }
    if (preferVertFirst) L(net, [a, { x: a.x, y: b.y }, b], w, 'F.Cu');
    else L(net, [a, { x: b.x, y: a.y }, b], w, 'F.Cu');
  };

  const vBusTop = 40;
  const vBusLow = 700;
  const vSpineL = 80;
  if (vcc) {
    add(vcc, { x: vSpineL, y: vBusTop }, { x: 2500, y: vBusTop }, 20, 'F.Cu');
    for (const [ref, num] of [['U1', 7], ['U2', 8], ['U3', 8], ['U5', 8], ['U5', 4],
      ['RA', 1], ['CD555', 1]]) {
      const p = pw(ref, num);
      if (p) add(vcc, { x: p.x, y: vBusTop }, p, 14, 'F.Cu');
    }
    addVia(vcc, { x: vSpineL, y: vBusTop });
    add(vcc, { x: vSpineL, y: vBusTop }, { x: vSpineL, y: vBusLow }, 18, 'B.Cu');
    addVia(vcc, { x: vSpineL, y: vBusLow });
    add(vcc, { x: vSpineL, y: vBusLow }, { x: 2100, y: vBusLow }, 18, 'B.Cu');
    for (const [ref, num] of [['CI1', 1], ['CI2', 1], ['CI3', 1],
      ['REG1', 1], ['REG2', 1], ['REG3', 1], ['CBI', 1], ['U4', 1]]) {
      const p = pw(ref, num);
      if (!p) continue;
      addVia(vcc, { x: p.x, y: vBusLow });
      add(vcc, { x: p.x, y: vBusLow }, p, 14, 'F.Cu');
    }
  }

  add(bufIn, pw('R1', 2), pw('U1', 3), 12, 'F.Cu');
  {
    const o = pw('U1', 6);
    const m = pw('U1', 2);
    if (o && m) L(out741, [o, { x: o.x + 55, y: o.y }, { x: o.x + 55, y: m.y + 55 },
      { x: m.x - 45, y: m.y + 55 }, { x: m.x - 45, y: m.y }, m], 12, 'F.Cu');
  }
  {
    const o = pw('U1', 6);
    const r = pw('R2', 1);
    if (o && r) L(out741, [o, { x: o.x + 55, y: o.y }, { x: o.x + 55, y: r.y }, r], 12, 'F.Cu');
  }
  add(tlIn, pw('R2', 2), pw('U2', 3), 12, 'F.Cu');
  add(tlOut, pw('U2', 1), pw('U2', 2), 10, 'F.Cu');
  add(u2b, pw('U2', 7), pw('U2', 6), 10, 'F.Cu');
  {
    const o = pw('U2', 1);
    const r = pw('R3', 1);
    if (o && r) L(tlOut, [o, { x: o.x - 50, y: o.y }, { x: o.x - 50, y: r.y }, r], 12, 'F.Cu');
  }
  add(lmIn, pw('R3', 2), pw('U3', 3), 12, 'F.Cu');
  {
    const out = pw('U3', 1);
    const inm = pw('U3', 2);
    const rf1 = pw('Rf3', 1);
    const rf2 = pw('Rf3', 2);
    if (out && rf2) L(lmOut, [out, { x: out.x - 50, y: out.y }, { x: out.x - 50, y: out.y - 70 },
      { x: rf2.x, y: out.y - 70 }, rf2], 12, 'F.Cu');
    if (inm && rf1) L(lmFb, [inm, { x: inm.x - 50, y: inm.y }, { x: inm.x - 50, y: rf1.y }, rf1], 12, 'F.Cu');
  }
  ortho(lmFb, pw('Rf3', 1), pw('Rg3', 1), 12, true);
  add(u3b, pw('U3', 7), pw('U3', 6), 10, 'F.Cu');
  if (gnd) {
    addVia(gnd, pw('U1', 4));
    addVia(gnd, pw('U2', 4));
    addVia(gnd, pw('U2', 5));
    addVia(gnd, pw('U3', 4));
    addVia(gnd, pw('U3', 5));
    addVia(gnd, pw('Rg3', 2));
  }

  add(disch, pw('RA', 2), pw('RB', 1), 12, 'F.Cu');
  ortho(disch, pw('RB', 1), pw('U5', 7), 12, false);
  add(cap555, pw('RB', 2), pw('CT', 1), 12, 'F.Cu');
  ortho(cap555, pw('CT', 1), pw('U5', 2), 12, false);
  {
    const t2 = pw('U5', 2);
    const t6 = pw('U5', 6);
    if (t2 && t6) L(cap555, [t2, { x: t2.x - 45, y: t2.y }, { x: t2.x - 45, y: t2.y - 50 },
      { x: t6.x + 45, y: t6.y - 50 }, { x: t6.x + 45, y: t6.y }, t6], 12, 'F.Cu');
  }
  add(out555, pw('U5', 3), pw('RLED', 1), 12, 'F.Cu');
  add(led555, pw('RLED', 2), pw('D555', 1), 12, 'F.Cu');
  add(ctrl, pw('U5', 5), pw('CC555', 1), 12, 'F.Cu');
  if (gnd) {
    addVia(gnd, pw('U5', 1));
    addVia(gnd, pw('CT', 2));
    addVia(gnd, pw('CD555', 2));
    addVia(gnd, pw('CC555', 2));
    addVia(gnd, pw('D555', 2));
  }

  for (let i = 1; i <= 3; i++) {
    const vout = i === 1 ? vout0 : i === 2 ? vout1 : vout2;
    add(vout, pw(`REG${i}`, 3), pw(`CO${i}`, 1), 14, 'F.Cu');
    add(vout, pw(`CO${i}`, 1), pw(`RL${i}`, 1), 12, 'F.Cu');
    if (gnd) {
      addVia(gnd, pw(`REG${i}`, 2));
      addVia(gnd, pw(`CI${i}`, 2));
      addVia(gnd, pw(`CO${i}`, 2));
      addVia(gnd, pw(`RL${i}`, 2));
    }
  }

  add(buckSw, pw('U4', 2), pw('LB', 1), 14, 'F.Cu');
  add(buckOut, pw('LB', 2), pw('CBO', 1), 14, 'F.Cu');
  ortho(buckOut, pw('CBO', 1), pw('U4', 4), 12, false);
  add(buckOut, pw('U4', 4), pw('U4', 5), 12, 'F.Cu');
  add(buckOut, pw('CBO', 1), pw('RFB', 1), 12, 'F.Cu');
  if (gnd) {
    addVia(gnd, pw('U4', 3));
    addVia(gnd, pw('CBI', 2));
    addVia(gnd, pw('CBO', 2));
    addVia(gnd, pw('RFB', 2));
  }

  const jGnd = pw('J1', 1);
  const jVcc = pw('J1', 2);
  const jSig = pw('J1', 3);
  const jLm = pw('J1', 4);
  const j555 = pw('J1', 5);
  const jV0 = pw('J1', 6);
  const jBk = pw('J1', 7);
  const jDs = pw('J1', 8);
  if (gnd && jGnd) addVia(gnd, jGnd);
  if (vcc && jVcc) {
    const col = jVcc.x - 60;
    L(vcc, [
      { x: 2500, y: vBusTop }, { x: col, y: vBusTop },
      { x: col, y: jVcc.y }, jVcc
    ], 18, 'F.Cu');
  }
  if (sig && jSig) {
    const r1a = pw('R1', 1);
    if (r1a) {
      const esc = { x: r1a.x - 40, y: r1a.y };
      const col = jSig.x - 100;
      add(sig, r1a, esc, 12, 'F.Cu');
      addVia(sig, esc);
      L(sig, [esc, { x: col, y: esc.y }, { x: col, y: jSig.y }], 12, 'B.Cu');
      addVia(sig, { x: col, y: jSig.y });
      add(sig, { x: col, y: jSig.y }, jSig, 12, 'F.Cu');
    }
  }
  const fanB = (net, src, jPad, colOff) => {
    if (!net || !src || !jPad) return;
    const col = jPad.x - colOff;
    const esc = { x: src.x + 35, y: src.y };
    add(net, src, esc, 12, 'F.Cu');
    addVia(net, esc);
    L(net, [esc, { x: col, y: esc.y }, { x: col, y: jPad.y }], 12, 'B.Cu');
    addVia(net, { x: col, y: jPad.y });
    add(net, { x: col, y: jPad.y }, jPad, 12, 'F.Cu');
  };
  fanB(lmOut, pw('U3', 1), jLm, 140);
  fanB(out555, pw('U5', 3), j555, 180);
  fanB(vout0, pw('REG1', 3), jV0, 220);
  fanB(buckOut, pw('CBO', 1), jBk, 260);
  fanB(disch, pw('U5', 7), jDs, 300);

  const named = [
    vcc, gnd, sig, bufIn, out741, tlIn, tlOut, u2b, lmIn, lmFb, lmOut, u3b,
    vout0, vout1, vout2, buckSw, buckOut, disch, cap555, out555, led555, ctrl
  ];
  return {
    trackCount: doc.tracks.length,
    netCount: named.filter(Boolean).length,
    viaCount: doc.vias.length
  };
}
